-- Slice Padel dashboard — connect the public Property Sites tab to the database
-- Run this once in Supabase: SQL Editor > New query > paste this whole file > Run

-- 1. Let the public dashboard (no login) read listings — it was authenticated-only before
create policy "anyone can read au_listings"
  on au_listings for select
  to anon, authenticated
  using (true);

-- 2. One-time import of the 28 listings currently hard-coded into index.html
on conflict (id) do nothing;
